/**
 * AI Video generator — produces short video clips via a VideoProvider (kie or fal).
 *
 * Reads prompts from either:
 *   - Video_Prompts.docx (dedicated file generated by the "Generate video prompts" button)
 *   - Scene_Prompts.docx (reuse the still-image scene prompts)
 *   - manual_prompts[] passed in the request
 *
 * Writes resulting .mp4 files into the project's configured video subfolder
 * (default "{code} - 10 Video Assembly Output" on new projects; legacy
 * projects keep their "{code} - 09 Video Assets" wording via project.json).
 *
 * NOTE: this is SEPARATE from the FFmpeg `video.ts` generator (which assembles finished
 * stills + narration into a final video). This generator produces the AI clips that the
 * FFmpeg assembler can later consume.
 */

import fs from 'fs/promises'
import path from 'path'
import * as pm from '../services/project-manager.js'
import * as jq from '../services/job-queue.js'
import { resolveSubfolderNames } from '../services/utils.js'
import { findEpisodeSubfolderDir, resolveEpisodeSubfolderDir } from '../services/media-root.js'
import { parseImagePromptsDocx } from '../lib/docx-parser.js'
import { downloadVideo } from '../lib/download-video.js'
import { SpeedTracker, throttle } from '../lib/speed-tracker.js'
import { registry } from '../providers/registry.js'
import { getApiKey } from '../services/app-secrets-store.js'
import { recordTask, recordTaskStrict, hashInput, readManifest, type Manifest } from '../services/task-manifest.js'
import { tryRecoverVideoFromManifest } from '../lib/manifest-recovery.js'
import { fileExistsWithContent, isCloudEvictedPlaceholder } from '../lib/http-retry.js'
import { resolveGenStudioLocalFanout } from '../lib/genstudio-runtime.js'
import { requireJobCompletion } from '../services/job-completion.js'
import { resolveGenStudioModelId, unavailableLegacyModelMessage } from '../services/genstudio-model-migration.js'
import { isGenStudioInsufficientCredits, refreshGenStudioAdmission } from '../lib/genstudio-client.js'
import type { GenerateAiVideoRequest, Job } from '../models/types.js'

async function findEpisodeDir(projectDir: string, code: string): Promise<string | null> {
  async function walk(dir: string, depth: number): Promise<string | null> {
    if (depth > 4) return null
    try {
      const entries = await fs.readdir(dir, { withFileTypes: true })
      for (const e of entries) {
        if (!e.isDirectory()) continue
        const clean = e.name.replace(/^✅\s*/, '')
        if (clean.startsWith(`${code} - `) || clean === code) return path.join(dir, e.name)
        const found = await walk(path.join(dir, e.name), depth + 1)
        if (found) return found
      }
    } catch {}
    return null
  }
  return walk(projectDir, 0)
}

async function findFileRecursive(dir: string, filenames: string[], depth = 0): Promise<string | null> {
  if (depth > 5) return null
  try {
    const entries = await fs.readdir(dir, { withFileTypes: true })
    for (const e of entries) {
      const full = path.join(dir, e.name)
      if (e.isFile() && filenames.includes(e.name)) return full
      if (e.isDirectory()) {
        const found = await findFileRecursive(full, filenames, depth + 1)
        if (found) return found
      }
    }
  } catch {}
  return null
}

async function loadPrompts(slug: string, episodeId: string, req: GenerateAiVideoRequest): Promise<Array<{ number: number; title: string; prompt: string }>> {
  const code = episodeId.toUpperCase()

  if (req.prompt_source === 'manual') {
    const list = req.manual_prompts || []
    return list.map((prompt, i) => ({ number: i + 1, title: `Clip ${i + 1}`, prompt }))
      .filter(p => p.prompt.trim().length > 0)
  }

  const outputRoot = await pm.getProjectOutputRoot(slug)
  if (!outputRoot) throw new Error('Project directory not found')

  if (req.prompt_source === 'video_prompts') {
    const found = await findFileRecursive(outputRoot, [`${code}_Video_Prompts.md`, `${code}_Video_Prompts.docx`])
    if (!found) throw new Error(`Could not find ${code}_Video_Prompts.md. Generate video prompts first.`)
    const parsed = await parseImagePromptsDocx(found)
    return parsed.scenes.length ? parsed.scenes : parsed.thumbnails
  }

  // scene_prompts fallback (reuse still-image prompts). Prefer .md, then legacy .docx.
  const found = await findFileRecursive(outputRoot, [
    `${code}_Scene_Prompts.md`, `${code}_Scene_Prompts.docx`,
    `${code}_Image_Prompts.md`, `${code}_Image_Prompts.docx`,
  ])
  if (!found) throw new Error(`Could not find scene prompts for ${code}. Generate them first.`)
  const parsed = await parseImagePromptsDocx(found)
  return parsed.scenes
}

async function loadSceneImages(slug: string, episodeId: string): Promise<Array<{ number: number; path: string }>> {
  const code = episodeId.toUpperCase()
  const outputRoot = await pm.getProjectOutputRoot(slug)
  if (!outputRoot) return []
  const names = await resolveSubfolderNames(slug, code)
  const epDir = await findEpisodeDir(outputRoot, code)
  if (!epDir) return []

  // Find the scene images folder (media-aware; honours ✅ prefix). Routes to
  // the external media root for a split project, else the iCloud episode dir.
  const imagesDir = await findEpisodeSubfolderDir(slug, code, 'images', epDir, names.images)
  if (!imagesDir) return []

  const result: Array<{ number: number; path: string }> = []
  const seen = new Set<number>()
  try {
    const files = (await fs.readdir(imagesDir)).sort()
    for (const file of files) {
      if (!/\.(png|jpg|jpeg|webp)$/i.test(file)) continue
      // Prefer v1 variants, fall back to first match
      const sceneMatch = file.match(/Scene(\d+)/i)
      if (!sceneMatch) continue
      const n = parseInt(sceneMatch[1])
      if (seen.has(n)) continue
      if (file.includes('_v1') || !files.some(f => f.includes(`Scene${sceneMatch[1]}`) && f.includes('_v1'))) {
        seen.add(n)
        result.push({ number: n, path: path.join(imagesDir, file) })
      }
    }
  } catch {}
  return result.sort((a, b) => a.number - b.number)
}

export async function generateAiVideo(job: Job): Promise<void> {
  const { project_slug, episode_id, params } = job
  const req = params as GenerateAiVideoRequest

  // Phase-wide download metrics (one tracker shared across every clip).
  // Veo clips can be hundreds of MB each — streaming bytes through the
  // tracker means the user sees live download speed instead of a frozen
  // "downloading…" line.
  const speedTracker = new SpeedTracker()
  let cumulativeBytes = 0
  const writeProgress = throttle(() => {
    const { speedBps } = speedTracker.update(cumulativeBytes)
    job.bytes_done = cumulativeBytes
    job.speed_bps = speedBps
  }, 250)
  const makeChunkCb = () => {
    let lastReceived = 0
    return (received: number, _total?: number) => {
      const delta = received - lastReceived
      if (delta > 0) {
        cumulativeBytes += delta
        lastReceived = received
        writeProgress()
      }
    }
  }

  const config = await pm.getConfig(project_slug)
  if (!config) throw new Error('Project config not found')

  const selectedModelId = req.model || ''
  const resolvedModelId = resolveGenStudioModelId('video', selectedModelId)
  if (!resolvedModelId) throw new Error(unavailableLegacyModelMessage('video', selectedModelId || '(none)'))
  const modelId = `genstudio-video:${resolvedModelId}`
  const modelConfig = {
    modes: ['frames'],
    provider: 'genstudio-video',
    provider_params: {
      provider: 'genstudio-video',
      duration_seconds: (req as any).duration_seconds,
      resolution: (req as any).resolution,
    },
  }
  const providerId = 'genstudio-video'
  const providerMaybe = registry.getVideoProvider(providerId)
  if (!providerMaybe) throw new Error(`No video provider registered for: ${providerId}`)
  // Re-bind to a `!`-narrowed const so closures below (processPrompt) see
  // the non-null type — TS doesn't flow narrowing into nested async fns.
  const provider = providerMaybe!

  const apiKey = await getApiKey('genstudio').catch(() => '')
  if (!apiKey) throw new Error('No GenStudio API key configured. Add it in Settings → This Mac.')

  const mode = 'frames' as const
  if (req.mode && req.mode !== mode) {
    throw new Error('Text-to-video has been retired. Generate the scene image first, then animate it.')
  }
  if (!modelConfig.modes?.includes('frames')) {
    throw new Error(`Model ${modelId} is not image-to-video capable.`)
  }

  let prompts = await loadPrompts(project_slug, episode_id, req)
  if (!prompts.length) throw new Error('No prompts found to generate from.')
  job.output_lines.push(`Loaded ${prompts.length} prompt(s)`)

  let sceneImages = await loadSceneImages(project_slug, episode_id)
  if (!sceneImages.length) throw new Error('No scene images found. Generate and approve scene images before creating motion clips.')
  if (req.scene_image_filenames?.length) {
    sceneImages = sceneImages.filter(s => req.scene_image_filenames!.some(f => s.path.endsWith(f)))
    const selectedNumbers = new Set(sceneImages.map(scene => scene.number))
    prompts = prompts.filter(prompt => selectedNumbers.has(prompt.number))
    if (!prompts.length) throw new Error('The selected scene image does not have a matching numbered prompt.')
  }
  const availableNumbers = new Set(sceneImages.map(scene => scene.number))
  const missingSourceImages = prompts.filter(prompt => !availableNumbers.has(prompt.number)).map(prompt => prompt.number)
  if (missingSourceImages.length) {
    throw new Error(
      `Missing source image(s) for scene ${missingSourceImages.join(', ')}. ` +
      'Generate those scene images first; Story Studio will not reuse a different scene image.',
    )
  }
  job.output_lines.push(`Matched ${sceneImages.length} exact scene image(s)`)

  // Resolve output dir via config subfolder names
  const code = episode_id.toUpperCase()
  const names = await resolveSubfolderNames(project_slug, code)
  const outputRoot = await pm.getProjectOutputRoot(project_slug)
  if (!outputRoot) throw new Error('Project directory not found')
  const epDir = await findEpisodeDir(outputRoot, code)
  if (!epDir) throw new Error(`Episode folder not found for ${code}. Create the episode (via script or ideas) first.`)
  const videoDir = await resolveEpisodeSubfolderDir(project_slug, code, 'video', epDir, names.video)
  await fs.mkdir(videoDir, { recursive: true })
  // Read the per-folder task manifest once so we can attempt free recovery
  // (existing-task poll) before issuing fresh submits. Covers both kie and
  // fal via tryRecoverVideoFromManifest.
  const videoManifest: Manifest = await readManifest(videoDir).catch(
    () => ({ schema_version: 1 as const, tasks: {} }),
  )

  const aspect = req.aspect_ratio || 'landscape'
  const nPerPrompt = Math.max(1, Math.min(4, req.number_of_videos_per_prompt || 1))
  const errors: string[] = []
  const isCancelled = () => jq.isCancelled(job.job_id)

  const admission = await refreshGenStudioAdmission(apiKey)
  const concurrency = resolveGenStudioLocalFanout(
    prompts.length,
    admission.burst_concurrency_ceiling,
  )
  if (prompts.length > 1) {
    job.output_lines.push(`Staging ${prompts.length} motion request(s); GenStudio account admission is authoritative.`)
  }

  async function processPrompt(index: number): Promise<void> {
    if (isCancelled()) return
    const p = prompts[index]!
    const stem = `${code}_Video${p.number.toString().padStart(2, '0')}`

    // A matching `.mp4` of non-zero size is a cache hit. A zero-byte file
    // from a prior aborted download is NOT — we re-run instead of leaving
    // the assembly step to choke on a truncated clip.
    const expectedVariants = Array.from({ length: nPerPrompt }, (_, variant) =>
      path.join(videoDir, `${stem}_v${variant + 1}.mp4`))
    const existingReady = await Promise.all(expectedVariants.map(fileExistsWithContent))
    if (!req.force && existingReady.every(Boolean)) {
      job.output_lines.push(`Skipping ${stem} (exists)`)
      return
    }
    // iCloud-evicted: video clips are the most expensive assets in this app
    // ($0.50–$2 each). If the local copy was evicted we MUST not re-bill.
    if (!req.force && await isCloudEvictedPlaceholder(path.join(videoDir, `${stem}_v1.mp4`))) {
      job.output_lines.push(
        `⚠ ${stem}_v1.mp4 is iCloud-evicted (right-click in Finder → Download Now). ` +
        `Skipped to avoid re-billing for an expensive video clip.`,
      )
      return
    }

    // Auto-recovery: before issuing a fresh (charged) submit, see if the
    // task-manifest sidecar has a stored task_id from a previous run. If
    // the provider still has the result, polling it is free; otherwise
    // we fall through to the regular submit path below.
    if (!req.force) {
      const recovered = await tryRecoverVideoFromManifest(
        videoManifest.tasks[`${stem}_v1.mp4`] || null,
        config as any,
        isCancelled,
      )
      if (recovered) {
        for (let v = 0; v < recovered.urls.length; v++) {
          const savePath = path.join(videoDir, `${stem}_v${v + 1}.mp4`)
          if (await fileExistsWithContent(savePath)) continue
          await downloadVideo(recovered.urls[v], savePath, makeChunkCb())
          job.output_lines.push(`  Saved ${path.basename(savePath)}`)
        }
        job.output_lines.push(
          `[${index + 1}/${prompts.length}] ${p.title || `Clip ${p.number}`} — recovered from existing task ` +
          `${recovered.taskId.slice(0, 12)}… (no charge)`,
        )
        return
      }
    }

    job.output_lines.push(`[${index + 1}/${prompts.length}] ${p.title || `Clip ${p.number}`}`)

    try {
      const startImage = sceneImages.find(s => s.number === p.number)
      if (!startImage) throw new Error(`Scene ${p.number} has no matching source image.`)
      const acceptedKeys: string[] = []

      const result = await provider.generateVideo({
        mode,
        prompt: p.prompt,
        apiKey,
        aspectRatio: aspect,
        numberOfVideos: nPerPrompt,
        modelId,
        startImagePath: startImage.path,
        providerParams: { ...(modelConfig as any).provider_params, operation: 'image-to-video' },
        idempotencyIdentity: `${project_slug}:${episode_id}:scene:${p.number}`,
        isCancelled,
        onJobAccepted: async (taskId, idempotencyKey, variantIndex) => {
          const filename = `${stem}_v${variantIndex + 1}.mp4`
          acceptedKeys[variantIndex] = idempotencyKey
          await recordTaskStrict(videoDir, filename, {
            provider: provider.meta.providerId || provider.meta.id,
            task_id: taskId,
            submitted_at: new Date().toISOString(),
            input_hash: hashInput(p.prompt),
            idempotency_key: idempotencyKey,
            operation: 'video',
            last_state: 'accepted',
          })
        },
      })
      if (!result.videoUrls.length) throw new Error(`${provider.meta.name} returned no video URL`)

      // Persist the provider task ids so the Repair button can later
      // recover any clip that failed to download without re-billing the
      // user. One manifest entry per output filename.
      const taskIds = result.taskIds || []
      const providerId = provider.meta.providerId || provider.meta.id
      for (let v = 0; v < result.videoUrls.length; v++) {
        const filename = `${stem}_v${v + 1}.mp4`
        const taskId = taskIds[v] || taskIds[0] || ''
        if (taskId) {
          await recordTask(videoDir, filename, {
            provider: providerId,
            task_id: taskId,
            submitted_at: new Date().toISOString(),
            input_hash: hashInput(p.prompt),
            ...(acceptedKeys[v] ? { idempotency_key: acceptedKeys[v] } : {}),
            operation: 'video',
            last_state: 'succeeded',
            ...(result.videoUrls[v] ? { result_url: result.videoUrls[v] } : {}),
          })
        }
      }

      for (let v = 0; v < result.videoUrls.length; v++) {
        const savePath = path.join(videoDir, `${stem}_v${v + 1}.mp4`)
        if (!req.force && await fileExistsWithContent(savePath)) continue
        await downloadVideo(result.videoUrls[v], savePath, makeChunkCb(), result.downloadHeaders)
        job.output_lines.push(`  Saved ${path.basename(savePath)}`)
      }
    } catch (e: any) {
      if (isGenStudioInsufficientCredits(e)) throw e
      // Settled-pool semantics: one clip failure doesn't kill the batch.
      job.output_lines.push(`  Failed: ${e.message}`)
      errors.push(`${p.title || `Clip ${p.number}`}: ${e.message}`)
    }
  }

  let cursor = 0
  let creditFailure: unknown
  async function worker(): Promise<void> {
    while (cursor < prompts.length) {
      if (isCancelled() || creditFailure) return
      const i = cursor++
      try {
        await processPrompt(i)
      } catch (error) {
        if (!isGenStudioInsufficientCredits(error)) throw error
        creditFailure ||= error
        return
      }
    }
  }
  await Promise.all(
    Array.from(
      { length: Math.min(concurrency, prompts.length) },
      () => worker(),
    ),
  )
  if (creditFailure) throw creditFailure

  // Partial-failure semantics: throw so the queue stamps status='error'
  // instead of 'done'. Same contract as images/audio generators. The queue's
  // own cancel check covers the cancelled case.
  if (errors.length) {
    job.output_lines.push(`Completed with ${errors.length} error(s)`)
    const preview = errors.slice(0, 3).join('; ')
    const suffix = errors.length > 3 ? `; +${errors.length - 3} more` : ''
    throw new Error(`${errors.length} clip(s) failed: ${preview}${suffix}`)
  }
  const expectedFiles = prompts.flatMap(prompt =>
    Array.from({ length: nPerPrompt }, (_, variant) => ({
      label: `Clip ${prompt.number} variant ${variant + 1}`,
      path: path.join(videoDir, `${code}_Video${prompt.number.toString().padStart(2, '0')}_v${variant + 1}.mp4`),
    })))
  const outputReady = await Promise.all(expectedFiles.map(file => fileExistsWithContent(file.path)))
  const missing = expectedFiles.filter((_, index) => !outputReady[index]).map(file => file.label)
  requireJobCompletion(job, {
    label: 'AI video generation', expected: expectedFiles.length,
    completed: expectedFiles.length - missing.length, missing,
    retry_hint: 'Existing clips and provider task IDs were kept. Retry recovers or generates only the missing variants.',
  })
  job.output_lines.push(`All clips saved to: ${videoDir}`)
  job.output_dir = videoDir
}
